export { BlMenu } from './menu.js';
export { BlMenuItem } from './menu-item.js';
export { BlMenuSeparator } from './menu-separator.js';
export { BlMenuGroup } from './menu-group.js';
export { BlMenuGroupLabel } from './menu-group-label.js';
export type { MenuItemVariant } from './menu-item.js';

import { LitElement, html, css } from 'lit';
import { customElement } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';

/**
 * A label for a menu group. Renders as a non-interactive heading.
 *
 * @element bl-menu-group-label
 * @slot - Label text.
 */
@customElement('bl-menu-group-label')
export class BlMenuGroupLabel extends LitElement {
  static override styles = [
    tokens,
    css`
      :host {
        display: block;
        padding: var(--bl-spacing-sm) var(--bl-spacing-sm) var(--bl-spacing-xs);
        font-family: var(--bl-font-family-base);
        font-size: var(--bl-font-size-xs);
        font-weight: 600;
        color: var(--bl-color-neutral-500);
        text-transform: uppercase;
        letter-spacing: 0.05em;
        user-select: none;
      }
    `,
  ];

  override connectedCallback(): void {
    super.connectedCallback();
    this.setAttribute('role', 'presentation');
  }

  protected override render() {
    return html`<slot></slot>`;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-menu-group-label': BlMenuGroupLabel;
  }
}

import { LitElement, html, css } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';

/**
 * A labelled group of menu items.
 *
 * @element bl-menu-group
 * @slot - `bl-menu-item` elements.
 */
@customElement('bl-menu-group')
export class BlMenuGroup extends LitElement {
  static override styles = [
    tokens,
    css`
      :host {
        display: block;
      }
    `,
  ];

  /** The group label. */
  @property()
  label = '';

  override connectedCallback(): void {
    super.connectedCallback();
    this.setAttribute('role', 'group');
  }

  override updated(changed: Map<string, unknown>): void {
    if (changed.has('label')) {
      this.setAttribute('aria-label', this.label);
    }
  }

  protected override render() {
    return html`<slot></slot>`;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-menu-group': BlMenuGroup;
  }
}

import { css } from 'lit';

export const menuItemStyles = css`
  :host {
    display: block;
  }

  :host([aria-disabled='true']) {
    pointer-events: none;
    opacity: 0.5;
  }

  .menu-item {
    display: flex;
    align-items: center;
    gap: var(--bl-spacing-sm);
    padding: var(--bl-spacing-xs) var(--bl-spacing-sm);
    cursor: pointer;
    font-family: var(--bl-font-family-base);
    font-size: var(--bl-font-size-sm);
    color: var(--bl-color-neutral-800);
    border-radius: var(--bl-radius-sm);
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    transition: background-color var(--bl-transition-fast);
    user-select: none;
    line-height: 1.5;
  }

  .menu-item:hover,
  :host([data-highlighted]) .menu-item {
    background-color: var(--bl-color-neutral-100);
  }

  :host([variant='danger']) .menu-item {
    color: var(--bl-color-danger-600);
  }

  :host([variant='danger']) .menu-item:hover,
  :host([variant='danger'][data-highlighted]) .menu-item {
    background-color: var(--bl-color-danger-50);
  }

  .menu-item:focus-visible {
    outline: 2px solid var(--bl-focus-ring-color);
    outline-offset: -2px;
  }
`;

import { LitElement, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { menuItemStyles } from './menu-item.styles.js';

export type MenuItemVariant = 'default' | 'danger';

/**
 * A single item in a dropdown or context menu.
 *
 * @element bl-menu-item
 * @slot - Item label content.
 * @csspart item - The menu item container.
 */
@customElement('bl-menu-item')
export class BlMenuItem extends LitElement {
  static override styles = [tokens, menuItemStyles];

  /** The value this item represents. */
  @property()
  value = '';

  /** Whether this item is disabled. */
  @property({ type: Boolean })
  disabled = false;

  /** Visual variant. */
  @property({ reflect: true })
  variant: MenuItemVariant = 'default';

  override connectedCallback(): void {
    super.connectedCallback();
    this.setAttribute('role', 'menuitem');
    if (!this.hasAttribute('tabindex')) {
      this.setAttribute('tabindex', '-1');
    }
    this.addEventListener('click', this._handleClick);
  }

  override disconnectedCallback(): void {
    super.disconnectedCallback();
    this.removeEventListener('click', this._handleClick);
  }

  override updated(changed: Map<string, unknown>): void {
    if (changed.has('disabled')) {
      this.setAttribute('aria-disabled', String(this.disabled));
    }
  }

  /** Set the highlighted (focus) state. */
  setHighlighted(highlighted: boolean): void {
    if (highlighted) {
      this.setAttribute('data-highlighted', '');
    } else {
      this.removeAttribute('data-highlighted');
    }
  }

  private _handleClick = (): void => {
    if (this.disabled) return;
    this.dispatchEvent(
      new CustomEvent('bl-menu-select', {
        detail: { value: this.value },
        composed: true,
        bubbles: true,
      }),
    );
  };

  protected override render() {
    return html`
      <div class="menu-item" part="item">
        <slot></slot>
      </div>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-menu-item': BlMenuItem;
  }
}

import { LitElement, html, css } from 'lit';
import { customElement } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';

/**
 * A visual separator between menu items.
 *
 * @element bl-menu-separator
 */
@customElement('bl-menu-separator')
export class BlMenuSeparator extends LitElement {
  static override styles = [
    tokens,
    css`
      :host {
        display: block;
        height: 1px;
        margin: var(--bl-spacing-xs) 0;
        background-color: var(--bl-color-neutral-200);
      }
    `,
  ];

  override connectedCallback(): void {
    super.connectedCallback();
    this.setAttribute('role', 'separator');
  }

  protected override render() {
    return html``;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-menu-separator': BlMenuSeparator;
  }
}

import { css } from 'lit';

export const menuStyles = css`
  :host {
    display: inline-block;
    position: relative;
  }

  .menu-surface {
    position: fixed;
    z-index: var(--bl-z-dropdown);
    min-width: 180px;
    max-height: 320px;
    overflow-y: auto;
    padding: var(--bl-spacing-xs);
    background-color: #fff;
    border: 1px solid var(--bl-color-neutral-200);
    border-radius: var(--bl-radius-md);
    box-shadow: var(--bl-shadow-lg);

    opacity: 0;
    transform: translateY(4px);
    transition:
      opacity var(--bl-animation-duration-fast) var(--bl-animation-easing-enter),
      transform var(--bl-animation-duration-fast) var(--bl-animation-easing-enter);
  }

  .menu-surface[data-state='entering'],
  .menu-surface[data-state='entered'] {
    opacity: 1;
    transform: translateY(0);
  }

  .menu-surface[data-state='exiting'] {
    opacity: 0;
    transform: translateY(4px);
    transition:
      opacity var(--bl-animation-duration-fast) var(--bl-animation-easing-exit),
      transform var(--bl-animation-duration-fast) var(--bl-animation-easing-exit);
  }
`;

import { LitElement, html, nothing } from 'lit';
import { customElement, property, state } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { menuStyles } from './menu.styles.js';
import { OverlayController } from '../controllers/overlay.js';
import { AnimationController } from '../controllers/animation.js';
import { ClickOutsideController } from '../controllers/click-outside.js';
import { RovingTabindexController } from '../controllers/roving-tabindex.js';
import { TypeaheadController } from '../controllers/typeahead.js';
import type { BlMenuItem } from './menu-item.js';
import type { Placement, VirtualElement } from '@floating-ui/dom';

/**
 * A dropdown menu with trigger support.
 *
 * @element bl-menu
 * @slot trigger - The element that opens the menu.
 * @slot - `bl-menu-item`, `bl-menu-separator`, `bl-menu-group` elements.
 * @fires bl-menu-select - Emitted when a menu item is selected.
 */
@customElement('bl-menu')
export class BlMenu extends LitElement {
  static override styles = [tokens, menuStyles];

  private _overlay = new OverlayController(this);
  private _animation = new AnimationController(this, { enterDuration: 150, exitDuration: 100 });
  private _clickOutside = new ClickOutsideController(this, {
    onClickOutside: () => { if (this.open) this._close(); },
    active: false,
  });
  private _roving = new RovingTabindexController(this, {
    selector: 'bl-menu-item:not([aria-disabled="true"])',
  });
  private _typeahead = new TypeaheadController(this, {
    selector: 'bl-menu-item:not([aria-disabled="true"])',
    onMatch: (item) => { (item as BlMenuItem).focus(); },
  });

  private _menuId = `bl-menu-${Math.random().toString(36).slice(2, 9)}`;

  /** Whether the menu is open. */
  @property({ type: Boolean, reflect: true })
  open = false;

  /** Preferred placement. */
  @property()
  placement: Placement = 'bottom-start';

  @state()
  private _visible = false;

  /**
   * A virtual reference element for positioning (used by context menu).
   * @internal
   */
  _virtualReference: VirtualElement | null = null;

  override connectedCallback(): void {
    super.connectedCallback();
    this.addEventListener('keydown', this._handleKeyDown);
    this.addEventListener('bl-menu-select', this._handleMenuSelect as EventListener);
  }

  override disconnectedCallback(): void {
    super.disconnectedCallback();
    this.removeEventListener('keydown', this._handleKeyDown);
    this.removeEventListener('bl-menu-select', this._handleMenuSelect as EventListener);
  }

  override updated(changed: Map<string, unknown>): void {
    if (changed.has('open')) {
      if (this.open) {
        this._openMenu();
      } else if (this._visible) {
        this._closeMenu();
      }
    }
  }

  private _getTrigger(): HTMLElement | null {
    const slot = this.shadowRoot!.querySelector<HTMLSlotElement>('slot[name="trigger"]');
    return slot?.assignedElements()[0] as HTMLElement | null;
  }

  private _getItems(): BlMenuItem[] {
    return Array.from(this.querySelectorAll<BlMenuItem>('bl-menu-item:not([aria-disabled="true"])'));
  }

  private _handleTriggerClick = (): void => {
    if (this.open) {
      this._close();
    } else {
      this.open = true;
    }
  };

  private _handleKeyDown = (e: KeyboardEvent): void => {
    if (!this.open) {
      if (e.key === 'Enter' || e.key === ' ' || e.key === 'ArrowDown') {
        e.preventDefault();
        this.open = true;
        return;
      }
    }

    if (e.key === 'Escape') {
      e.preventDefault();
      e.stopPropagation();
      this._close();
    }
  };

  private _handleMenuSelect = (e: CustomEvent<{ value: string }>): void => {
    e.stopPropagation();
    this._close();
    this.dispatchEvent(
      new CustomEvent('bl-menu-select', {
        detail: { value: e.detail.value },
        composed: true,
        bubbles: true,
      }),
    );
  };

  private async _openMenu(): Promise<void> {
    if (this._visible) return;
    this._visible = true;
    await this.updateComplete;

    const reference = this._virtualReference ?? this._getTrigger();
    const surface = this.shadowRoot!.querySelector<HTMLElement>('.menu-surface');
    if (!reference || !surface) return;

    const trigger = this._getTrigger();
    if (trigger) {
      trigger.setAttribute('aria-expanded', 'true');
      trigger.setAttribute('aria-haspopup', 'menu');
      trigger.setAttribute('aria-controls', this._menuId);
    }

    this._overlay.setPlacement(this.placement);
    this._overlay.show(reference as HTMLElement, surface);
    this._animation.enter(surface);
    this._clickOutside.active = true;

    // Focus first item
    requestAnimationFrame(() => {
      const items = this._getItems();
      if (items.length > 0) {
        this._roving.setCurrentIndex(0);
        items[0]?.focus();
      }
    });
  }

  private async _closeMenu(): Promise<void> {
    if (!this._visible) return;

    const surface = this.shadowRoot!.querySelector<HTMLElement>('.menu-surface');
    if (surface) {
      await this._animation.exit(surface);
    }

    this._overlay.hide();
    this._clickOutside.active = false;
    this._visible = false;
    this._virtualReference = null;

    const trigger = this._getTrigger();
    if (trigger) {
      trigger.setAttribute('aria-expanded', 'false');
      trigger.removeAttribute('aria-controls');
      trigger.focus();
    }
  }

  private _close(): void {
    this.open = false;
  }

  private _handleSlotChange(): void {
    const trigger = this._getTrigger();
    if (!trigger) return;
    trigger.removeEventListener('click', this._handleTriggerClick);
    trigger.addEventListener('click', this._handleTriggerClick);
    trigger.setAttribute('aria-expanded', String(this.open));
    trigger.setAttribute('aria-haspopup', 'menu');
  }

  protected override render() {
    return html`
      <slot name="trigger" @slotchange=${this._handleSlotChange}></slot>
      ${this._visible
        ? html`
            <div
              class="menu-surface"
              id=${this._menuId}
              role="menu"
            >
              <slot></slot>
            </div>
          `
        : nothing}
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-menu': BlMenu;
  }
}
